import{z as n,x as A,o as r,c as p,q as s,j as l,D as t,d as E,s as o,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"查询改写","description":"","frontmatter":{"title":"查询改写","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/query-rewrite.md","filePath":"cs/query-rewrite.md","lastUpdated":1791413859000}'),d={name:"cs/query-rewrite.md"};function m(h,a,u,c,F,_){const i=A("Mermaid");return r(),p("div",null,[a[2]||(a[2]=s('<h1 id="查询改写" tabindex="-1">查询改写 <a class="header-anchor" href="#查询改写" aria-label="Permalink to &quot;查询改写&quot;">​</a></h1><div class="epigraph"><p>先用代数律把树变得更瘦，再估代价；下推与结合律改的是形状，不是用户写的那句话。</p><footer>—— 据 Ullman 对逻辑优化；Chaudhuri 对优化器架构的整理</footer></div><p><a href="/cs/histogram-card">上一课</a>给计划树上的数字。本课不重写选择率公式。缺口是：许多等价逻辑树，有的让选择更早、连接更小。改写在逻辑层用代数律变换，再交给物理搜索与代价。没有改写，优化器只能在用户写出的那一棵歪树上估数字。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>用户可能先写笛卡尔积再过滤，或把能下推的谓词留在顶层。指称相同，中间结果可以差几个数量级。<span class="marginnote">可以把它想象成淘金：先在河边把大部分石头筛掉（谓词下推），再把剩下的少量矿砂运进车间（连接）——数据越早变瘦，后面每一步的搬运与加工都跟着便宜。</span>缺口不是新 SQL，而是<strong>保持指称的变换</strong>：选择下推、投影下推、连接结合律与交换律、把子查询改成连接。本课只做逻辑等价，不保证改完一定更快——更快由代价判定。</p><p><span class="marginnote">集合语义下选择与连接交换较干净；NULL 与包会打碎部分律。SQL 课已承认三值；改写器必须标哪些变换在当前语义下合法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把 SQL 收成逻辑树后，反复应用：\\(\\sigma_\\theta(R\\bowtie S)\\) 在 \\(\\theta\\) 只涉及 \\(R\\) 时变成 \\(\\sigma_\\theta(R)\\bowtie S\\)；投影只保留后继需要的列；连接树按结合律重括号。视图展开是改写的一种：把视图名换成定义树。本课不引入基于规则的引擎实现，只锁定变换前后指称相同。</p>',8)),(r(),l(B,null,{default:t(()=>[o(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SQL%5B%22%E5%A3%B0%E6%98%8E%20SQL%22%5D%20--%3E%20LOG%5B%22%E9%80%BB%E8%BE%91%E6%A0%91%22%5D%0A%20%20LOG%20--%3E%20RW%5B%22%E4%BB%A3%E6%95%B0%E6%94%B9%E5%86%99%22%5D%0A%20%20RW%20--%3E%20EST%5B%22%E4%BB%A3%E4%BB%B7%20%2B%20%E7%89%A9%E7%90%86%E6%90%9C%E7%B4%A2%22%5D%0A%20%20RW%20--%3E%20NF%5B%22%E5%90%8E%E8%AF%BE%3A%20%E8%8C%83%E5%BC%8F%E4%B8%8E%E5%88%86%E8%A7%A3%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("改写缩小中间基数，使后课的哈希表与排序输入变小；"),e("span",{class:"marginnote"},"数字实例：\\(R\\) 有 100 万行、满足谓词的只有 1000 行，\\(S\\) 有 10 万行——先过滤再连接，连接的输入量级从 \\(10^{6}\\times10^{5}=10^{11}\\) 掉到约 \\(10^{3}\\times10^{5}=10^{8}\\)，中间数据直接少三个数量级。"),E("也可能为了用某一索引而"),e("strong",null,"故意"),E("保留某个谓词形状。启发式（始终下推）与基于代价的变换可以并存：先做几乎总赚的下推，再对连接顺序做代价搜索。相关子查询去相关，是把演算写法改回连接，以便用"),e("a",{href:"/cs/join-algorithms"},"连接算法"),E("。")],-1)),(r(),l(B,null,{default:t(()=>[o(i,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20BEFORE%5B%22%E6%94%B9%E5%86%99%E5%89%8D%EF%BC%9A%E5%85%88%E5%A4%A7%E8%BF%9E%E5%90%8E%E5%86%8D%E8%BF%87%E6%BB%A4%22%5D%20--%3E%20JOIN%5B%22R%20%E2%8B%88%20S%20%E5%85%A8%E9%87%8F%E8%BF%9E%E6%8E%A5%22%5D%0A%20%20JOIN%20--%3E%20FILT%5B%22%CF%83%20%E8%BF%87%E6%BB%A4%EF%BC%8C%E7%BB%9D%E5%A4%A7%E5%A4%9A%E6%95%B0%E8%A1%8C%E8%A2%AB%E4%B8%A2%E5%BC%83%22%5D%0A%20%20AFTER%5B%22%E6%94%B9%E5%86%99%E5%90%8E%EF%BC%9A%E5%85%88%E8%BF%87%E6%BB%A4%E5%86%8D%E8%BF%9E%E6%8E%A5%22%5D%20--%3E%20F1%5B%22%CF%83%20%E4%BD%9C%E7%94%A8%E5%9C%A8%20R%20%E4%B8%8A%22%5D%0A%20%20AFTER%20--%3E%20F2%5B%22S%20%E4%BF%9D%E6%8C%81%E5%8E%9F%E6%A0%B7%22%5D%0A%20%20F1%20--%3E%20J2%5B%22%E8%BE%93%E5%85%A5%E5%B0%8F%E5%BE%97%E5%A4%9A%E7%9A%84%E8%BF%9E%E6%8E%A5%22%5D%0A%20%20F2%20--%3E%20J2%0A%20%20J2%20--%3E%20SAME%5B%22%E7%BB%93%E6%9E%9C%E4%B8%8E%E6%94%B9%E5%86%99%E5%89%8D%E5%90%8C%E6%8C%87%E7%A7%B0%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=s('<p><span class="marginnote">初学者容易以为改写是在改用户写的 SQL 文本；实际上改写发生在优化器内部的逻辑树上，用户那句 SQL 一个字都没变——变的是树的形状与谓词的求值位置。</span></p><p>本课不把「提示」当模型。提示是绕过搜索的工程旋钮；主干仍是等价变换加代价。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>改写不修复错误的统计，也不替代完整性。不能把有副作用的函数随便下推。分组、极限、窗口对交换律不友好，本课只点名：这些算子是改写的防火墙。也不把规范化（模式分解）与查询改写混成一步——后课动的是模式，不是这一棵查询树。</p><p>外连接会挡住某些下推：NULL 填充使「先过滤再连接」与「先连接再过滤」不再同指称。后课默认：优化器先改逻辑树再估代价；谈到等价，指的是代数指称，不是计划字符串相同。</p><p>改写器与代价估计交替：先做几乎总合法的下推，再对连接顺序搜。指称不变是硬约束，快是软目标。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>相关子查询去相关是为了进入连接算法，不是为了换一种 SQL 方言。</p></li><li><p>有副作用的 UDF 是改写防火墙，本课不当成可下推的 \\(\\sigma\\)。</p></li><li><p>代价已在；本课用代数律改逻辑树的形状。</p></li><li><p>下推与结合律保指称；快不快仍看估计。</p></li><li><p>模式为何难改写、要不要分解，是后课缺口。</p></li><li><p>出处：Garcia-Molina, Ullman and Widom；Chaudhuri, <em>An Overview of Query Optimization</em>, 1998。</p></li></ul>',8))])}const C=n(d,[["render",m]]);export{f as __pageData,C as default};
